fn is_non_prime(n: u64) -> bool {
    // n is at least 2 by problem statement, so no need to handle n < 2.
    if n == 2 {
        // 2 is prime, so no non-trivial divisors.
        return false;
    }

    // Iterate k from 2 up to sqrt(n)
    // If any k divides n, n is non-prime.
    let limit = (n as f64).sqrt() as u64;
    for k in 2..=limit {
        if n % k == 0 {
            return true;
        }
    }

    // No divisor found in [2, n-1], so n is prime.
    false
}